var template charstring v_char1 := "MYCHAR", 
     v_char2, 
     v_char3 := pattern "abc?[a-z]";
  v_char2 := v_char1[1]; // v_char2 will be equal to "Y" after the assignment
  v_char2 := v_char3[3]; // v_char2 will be equal to pattern "?" after the assignment
  v_char2 := v_char3[4]; // v_char2 will be equal to pattern "[a-z]" after the assignment
  v_char3 := ?;
  v_char2 := v_char3[0]; // v_char2 will contain pattern "?" after the assignment
  v_char3 := pattern "abc?[a-z]";
  v_char3[6] := pattern "x+"; // v_char3 will contain pattern "abc?[a-z]?x+" after the assignment
  v_char3 := "abc";
  v_char3[4] := pattern "[a-f][g-k]"; // v_char3 will change to pattern "abc([a-f][g-k])"
  v_char3[2] := "test"; // will produce an error as the character string contains more than one
             // character
  var template octetstring v_oct1 := '01234567890ABCDEF'O, 
     v_oct2, 
     v_oct3 := '01??AB*'O;
  v_oct2 := v_oct1[1]; // v_oct2 will be equal to '23'O after the assignment
  v_oct2 := v_oct3[2]; // v_oct2 will be equal to '?'O after the assignment
  v_oct3 := *;
  v_oct2 := v_oct3[0]; // v_oct2 will contain '?'O ifpresent after the assignment
  v_oct1[2] := '?'O; // v_oct1 will contain '0123?67890ABCDEF'O after the assignment
  v_oct3 := '0123'O;
  v_oct3[4] := 'FF'O; // v_oct3 will change to '0123??FF'O 
  v_oct1 := 'FFFF'O;
  v_oct2 := v_oct1[10] // will produce an error as the index is greater than the length of v_oct1_

